     1	// 物理设施适配器抽象接口（Physical Facility Adapter）。
     2	//
     3	// 背景：调度系统在多层厂区或跨防火分区运行时，需要与现场物理设施联动
     4	// （如自动门/风淋门、电梯/提升机、充电机等）。
     5	// 过去系统中仅有内存级的状态和资源字典判定（SelectFacilityActionResource），
     6	// 缺乏向下对接现场设施控制层（如 PLC、OPC-UA、Modbus 或专用电梯调度器）的适配接口。
     7	//
     8	// 本模块定义核心抽象接口 IFacilityAdapter 与通用数据结构：
     9	// - FacilityType：设施类型（门、电梯、充电桩、未知）
    10	// - FacilityStatus：设施状态（就绪、忙碌、故障、离线）
    11	// - FacilityCommandResult：设施操作结果
    12	// 并提供纯内存 / 测试用的 MockFacilityAdapter，保证：
    13	// 1. 纯 C++、无 ROS / OPC-UA 强制运行时依赖，宿主单测 100% 可测。
    14	// 2. 具备异步/状态机友好的查询与指令执行语义，为后续 OPC-UA 插件预留无缝扩展点。
    15	#pragma once
    16	
    17	#include <cstdint>
    18	#include <memory>
    19	#include <string>
    20	#include <vector>
    21	
    22	namespace amr_dispatcher_core::facility {
    23	
    24	enum class FacilityType {
    25	  kUnknown,
    26	  kDoor,
    27	  kElevator,
    28	  kCharger,
    29	};
    30	
    31	enum class FacilityState {
    32	  kOffline,
    33	  kReady,
    34	  kBusy,
    35	  kFault,
    36	};
    37	
    38	struct FacilityCommandResult {
    39	  bool success = false;
    40	  std::string facility_id;
    41	  std::string action;
    42	  std::string message;
    43	  int error_code = 0;
    44	};
    45	
    46	struct FacilityStateReport {
    47	  std::string facility_id;
    48	  FacilityType type = FacilityType::kUnknown;
    49	  FacilityState state = FacilityState::kOffline;
    50	  std::string current_floor;
    51	  std::string door_status;  // "open", "closed", "opening", "closing"
    52	  bool locked = false;
    53	  std::string locked_by;
    54	};
    55	
    56	class IFacilityAdapter {
    57	 public:
    58	  virtual ~IFacilityAdapter() = default;
    59	
    60	  // 基础元信息
    61	  virtual std::string GetFacilityId() const = 0;
    62	  virtual FacilityType GetFacilityType() const = 0;
    63	
    64	  // 查询设施当前实时状态
    65	  virtual FacilityStateReport QueryState() = 0;
    66	
    67	  // 设施动作控制
    68	  // 门操作：open, close, unlock
    69	  // 电梯操作：call, send_to_floor, open_door, close_door
    70	  virtual FacilityCommandResult ExecuteAction(const std::string& action,
    71	                                              const std::string& params = "") = 0;
    72	
    73	  // 预约锁与占用释放
    74	  virtual bool AcquireLock(const std::string& holder_id) = 0;
    75	  virtual bool ReleaseLock(const std::string& holder_id) = 0;
    76	};
    77	
    78	// 内存 Mock 适配器，用于单元测试与本地仿真
    79	class MockFacilityAdapter : public IFacilityAdapter {
    80	 public:
    81	  MockFacilityAdapter(std::string facility_id, FacilityType type);
    82	
    83	  std::string GetFacilityId() const override { return facility_id_; }
    84	  FacilityType GetFacilityType() const override { return type_; }
    85	
    86	  FacilityStateReport QueryState() override;
    87	  FacilityCommandResult ExecuteAction(const std::string& action,
    88	                                      const std::string& params = "") override;
    89	
    90	  bool AcquireLock(const std::string& holder_id) override;
    91	  bool ReleaseLock(const std::string& holder_id) override;
    92	
    93	  // 仿真辅助注入接口
    94	  void SetState(FacilityState state) { state_ = state; }
    95	  void SetCurrentFloor(const std::string& floor) { current_floor_ = floor; }
    96	  void SetDoorStatus(const std::string& status) { door_status_ = status; }
    97	
    98	 private:
    99	  std::string facility_id_;
   100	  FacilityType type_;
   101	  FacilityState state_{FacilityState::kReady};
   102	  std::string current_floor_{"1"};
   103	  std::string door_status_{"closed"};
   104	  bool locked_{false};
   105	  std::string locked_by_;
   106	};
   107	
   108	}  // namespace amr_dispatcher_core::facility
