    20	FacilityCommandResult MockFacilityAdapter::ExecuteAction(const std::string& action,
    21	                                                        const std::string& params) {
    22	  FacilityCommandResult res;
    23	  res.facility_id = facility_id_;
    24	  res.action = action;
    25	
    26	  if (state_ == FacilityState::kFault || state_ == FacilityState::kOffline) {
    27	    res.success = false;
    28	    res.message = "facility is not operational (fault or offline)";
    29	    res.error_code = 1;
    30	    return res;
    31	  }
    32	
    33	  if (type_ == FacilityType::kDoor) {
    34	    if (action == "open") {
    35	      door_status_ = "open";
    36	      res.success = true;
    37	      res.message = "door opened successfully";
    38	      return res;
    39	    }
    40	    if (action == "close") {
    41	      door_status_ = "closed";
    42	      res.success = true;
    43	      res.message = "door closed successfully";
    44	      return res;
    45	    }
    46	  } else if (type_ == FacilityType::kElevator) {
    47	    if (action == "call" || action == "send_to_floor") {
    48	      if (!params.empty()) {
    49	        current_floor_ = params;
    50	      }
    51	      res.success = true;
    52	      res.message = "elevator moved to floor " + current_floor_;
    53	      return res;
    54	    }
    55	    if (action == "open_door") {
    56	      door_status_ = "open";
    57	      res.success = true;
    58	      res.message = "elevator door opened";
    59	      return res;
    60	    }
    61	    if (action == "close_door") {
    62	      door_status_ = "closed";
    63	      res.success = true;
    64	      res.message = "elevator door closed";
    65	      return res;
    66	    }
    67	  }
    68	
    69	  res.success = false;
    70	  res.message = "unsupported action: " + action;
    71	  res.error_code = 2;
    72	  return res;
    73	}
