     9	std::string Trim(const std::string& value) {
    10	  const auto first = value.find_first_not_of(" \t\r\n");
    11	  if (first == std::string::npos) {
    12	    return "";
    13	  }
    14	  const auto last = value.find_last_not_of(" \t\r\n");
    15	  return value.substr(first, last - first + 1);
    16	}
    17	
    18	std::optional<std::string> ValueAfterColon(const std::string& line, const std::string& key) {
    19	  const std::string prefix = key + ":";
    20	  if (line.rfind(prefix, 0) != 0) {
    21	    return std::nullopt;
    22	  }
    23	  return Trim(line.substr(prefix.size()));
    24	}
    25	
    26	bool ParseBool(const std::string& value) {
    27	  return value == "true" || value == "True" || value == "1";
    28	}
    29	
    30	}  // namespace
    31	
    32	std::optional<FacilityCatalog> LoadFacilityCatalog(const std::filesystem::path& path) {
    33	  std::ifstream input(path);
    34	  if (!input) {
    35	    return std::nullopt;
    36	  }
    37	
    38	  FacilityCatalog catalog;
    39	  FacilityResource current;
    40	  bool in_resource = false;
    41	  bool has_id = false;
    42	  bool has_type = false;
    43	  bool incomplete = false;  // 有 id 却缺 type 的记录：配置错误，不得静默丢弃
    44	
    45	  auto flush_resource = [&]() {
    46	    if (in_resource && has_id) {
    47	      if (!has_type) {
    48	        incomplete = true;  // 记录不完整 -> 整份目录判负
    49	      } else {
    50	        catalog.resources.push_back(current);
    51	      }
    52	    }
    53	    current = FacilityResource{};
    54	    in_resource = false;
    55	    has_id = false;
    56	    has_type = false;
    57	  };
    58	
    59	  std::string section;
    60	  std::string line;
    61	  while (std::getline(input, line)) {
    62	    line = Trim(line);
    63	    if (line.empty() || line.front() == '#') {
    64	      continue;
    65	    }
    66	    if (line == "resources:" || line == "facilities:") {
    67	      flush_resource();
    68	      section = line.substr(0, line.size() - 1);
    69	      continue;
    70	    }
    71	    if (line.rfind("- ", 0) == 0) {
    72	      if (section != "resources" && section != "facilities") {
    73	        continue;
    74	      }
    75	      flush_resource();
    76	      in_resource = true;
    77	      line = Trim(line.substr(2));
    78	    }
    79	    if (!in_resource) {
    80	      continue;
    81	    }
    82	    if (auto value = ValueAfterColon(line, "id")) {
    83	      current.id = *value;
    84	      has_id = !current.id.empty();
    85	      continue;
    86	    }
    87	    if (auto value = ValueAfterColon(line, "type")) {
    88	      current.type = *value;
    89	      has_type = !current.type.empty();
    90	      continue;
    91	    }
    92	    if (auto value = ValueAfterColon(line, "station_id")) {
    93	      current.station_id = *value;
    94	      continue;
    95	    }
    96	    if (auto value = ValueAfterColon(line, "enabled")) {
    97	      current.enabled = ParseBool(*value);
    98	      continue;
    99	    }
   100	    if (auto value = ValueAfterColon(line, "exclusive")) {
   101	      current.exclusive = ParseBool(*value);
   102	      continue;
   103	    }
   104	  }
   105	  flush_resource();
   106	  if (incomplete) {
   107	    return std::nullopt;  // 存在缺 type 的资源记录 -> 配置错误，整份判负
   108	  }
   109	
   110	  std::string message;
   111	  if (!ValidateFacilityCatalog(catalog, &message)) {
   112	    return std::nullopt;
   113	  }
   114	  return catalog;
   115	}
   116	
   117	const FacilityResource* FindFacilityResource(
   118	    const FacilityCatalog& catalog, const std::string& resource_id) {
   119	  for (const auto& resource : catalog.resources) {
   120	    if (resource.id == resource_id) {
   121	      return &resource;
   122	    }
   123	  }
   124	  return nullptr;
   125	}
   126	
   127	const FacilityResource* FindFirstAvailableResource(
   128	    const FacilityCatalog& catalog, const std::string& resource_type,
   129	    const std::vector<std::string>& unavailable_resource_ids) {
   130	  for (const auto& resource : catalog.resources) {
   131	    if (!resource.enabled || resource.type != resource_type) {
   132	      continue;
   133	    }
   134	    bool unavailable = false;
   135	    for (const auto& unavailable_id : unavailable_resource_ids) {
   136	      if (resource.id == unavailable_id) {
   137	        unavailable = true;
   138	        break;
   139	      }
   140	    }
   141	    if (!unavailable) {
   142	      return &resource;
   143	    }
   144	  }
   145	  return nullptr;
   146	}
   147	
   148	bool ValidateFacilityCatalog(const FacilityCatalog& catalog, std::string* message) {
   149	  std::unordered_set<std::string> ids;
   150	  for (const auto& resource : catalog.resources) {
   151	    if (resource.id.empty()) {
   152	      if (message != nullptr) {
   153	        *message = "facility resource id is empty";
   154	      }
   155	      return false;
   156	    }
   157	    if (resource.type.empty()) {
   158	      if (message != nullptr) {
   159	        *message = "facility resource type is empty: " + resource.id;
   160	      }
   161	      return false;
   162	    }
   163	    if (!ids.insert(resource.id).second) {
   164	      if (message != nullptr) {
   165	        *message = "duplicate facility resource id: " + resource.id;
   166	      }
   167	      return false;
   168	    }
   169	  }
   170	  if (message != nullptr) {
   171	    *message = "facility catalog ok";
   172	  }
   173	  return true;
   174	}
   175	
   176	}  // namespace amr_dispatcher_core::facility
