     5	bool FacilityResourceAvailable(
     6	    const FacilityResource& resource, const FacilityReservationMap& reservations) {
     7	  if (!resource.enabled) {
     8	    return false;
     9	  }
    10	  return !resource.exclusive || reservations.find(resource.id) == reservations.end();
    11	}
    12	
    13	std::string FacilityResourceStatus(
    14	    const FacilityResource& resource, const FacilityReservationMap& reservations) {
    15	  if (!resource.enabled) {
    16	    return "disabled";
    17	  }
    18	  const auto reservation = reservations.find(resource.id);
    19	  return reservation == reservations.end() ? "available" : reservation->second.status;
    20	}
    21	
    22	FacilityResourceListProjection BuildFacilityResourceListProjection(
    23	    const FacilityCatalog& catalog,
    24	    const FacilityReservationMap& reservations,
    25	    const FacilityResourceListRequest& request) {
    26	  FacilityResourceListProjection projection;
    27	  for (const auto& resource : catalog.resources) {
    28	    if (!request.include_disabled && !resource.enabled) {
    29	      continue;
    30	    }
    31	    if (!request.resource_type.empty() && resource.type != request.resource_type) {
    32	      continue;
    33	    }
    34	    projection.resource_ids.push_back(resource.id);
    35	    projection.resource_types.push_back(resource.type);
    36	    projection.station_ids.push_back(resource.station_id);
    37	    projection.enabled.push_back(resource.enabled);
    38	    projection.available.push_back(FacilityResourceAvailable(resource, reservations));
    39	    const auto reservation = reservations.find(resource.id);
    40	    projection.holder_ids.push_back(
    41	        reservation == reservations.end() ? "" : reservation->second.holder_id);
    42	    projection.status.push_back(FacilityResourceStatus(resource, reservations));
    43	  }
    44	  projection.message =
    45	      "loaded " + std::to_string(projection.resource_ids.size()) + " facility resource(s)";
    46	  return projection;
    47	}
    48	
    49	FacilityResourceStateProjection BuildFacilityResourceStateProjection(
    50	    const FacilityResource& resource,
    51	    const FacilityReservationMap& reservations,
    52	    const std::string& resource_label) {
    53	  FacilityResourceStateProjection projection;
    54	  projection.resource_id = resource.id;
    55	  projection.station_id = resource.station_id;
    56	  projection.available = FacilityResourceAvailable(resource, reservations);
    57	  const auto reservation = reservations.find(resource.id);
    58	  projection.holder_id = reservation == reservations.end() ? "" : reservation->second.holder_id;
    59	  projection.status = FacilityResourceStatus(resource, reservations);
    60	  projection.message = "loaded " + resource_label + " state " + resource.id;
    61	  return projection;
    62	}
    63	
    64	std::vector<std::string> ReservedResourceIds(const FacilityReservationMap& reservations) {
    65	  std::vector<std::string> ids;
    66	  ids.reserve(reservations.size());
    67	  for (const auto& [resource_id, reservation] : reservations) {
    68	    (void)reservation;
    69	    ids.push_back(resource_id);
    70	  }
    71	  return ids;
    72	}
    73	
    74	std::size_t ReleaseResourcesForHolder(
    75	    FacilityReservationMap& reservations, const std::string& holder_id) {
    76	  std::size_t released = 0U;
    77	  for (auto it = reservations.begin(); it != reservations.end();) {
    78	    if (it->second.holder_id == holder_id) {
    79	      it = reservations.erase(it);
    80	      ++released;
    81	    } else {
    82	      ++it;
    83	    }
    84	  }
    85	  return released;
    86	}
    87	
    88	FacilityReservationResult ReserveFacilityResource(
    89	    FacilityReservationMap& reservations, const FacilityResource& resource,
    90	    const std::string& holder_id, const std::string& mission_id,
    91	    const bool release_existing_for_holder) {
    92	  FacilityReservationResult result;
    93	  result.resource_id = resource.id;
    94	  result.holder_id = holder_id;
    95	
    96	  if (!resource.enabled) {
    97	    result.status = "disabled";
    98	    result.message = "facility resource disabled: " + resource.id;
    99	    return result;
   100	  }
   101	  const auto existing = reservations.find(resource.id);
   102	  if (resource.exclusive && existing != reservations.end() &&
   103	      existing->second.holder_id != holder_id) {
   104	    // A6 先查后放：冲突未通过则直接失败，不得有任何副作用（holder 的既有持有必须保留）
   105	    result.holder_id = existing->second.holder_id;
   106	    result.status = existing->second.status;
   107	    result.message = "facility resource already reserved: " + resource.id;
   108	    return result;
   109	  }
   110	  // 冲突检查全部通过后才释放 holder 的旧持有，避免预约失败连带丢锁
   111	  if (release_existing_for_holder) {
   112	    ReleaseResourcesForHolder(reservations, holder_id);
   113	  }
   114	
   115	  reservations[resource.id] = ResourceReservation{holder_id, mission_id, "reserved"};
   116	  result.success = true;
   117	  result.status = "reserved";
   118	  result.message = "reserved facility resource " + resource.id + " for " + holder_id;
   119	  return result;
   120	}
   121	
   122	FacilityReservationResult ReleaseFacilityResource(
   123	    FacilityReservationMap& reservations, const std::string& resource_id,
   124	    const std::string& holder_id) {
   125	  FacilityReservationResult result;
   126	  result.resource_id = resource_id;
   127	  const auto existing = reservations.find(resource_id);
   128	  if (existing == reservations.end()) {
   129	    result.success = true;
   130	    result.status = "available";
   131	    result.message = "facility resource already available: " + resource_id;
   132	    return result;
   133	  }
   134	  if (!holder_id.empty() && existing->second.holder_id != holder_id) {
   135	    result.holder_id = existing->second.holder_id;
   136	    result.status = existing->second.status;
   137	    result.message = "facility resource held by " + existing->second.holder_id;
   138	    return result;
   139	  }
   140	
   141	  reservations.erase(existing);
   142	  result.success = true;
   143	  result.status = "available";
   144	  result.message = "released facility resource " + resource_id;
   145	  return result;
   146	}
   147	
   148	bool MarkResourceOccupiedForMission(
   149	    FacilityReservationMap& reservations, MissionResourceMap& resource_by_mission,
   150	    const std::string& mission_id) {
   151	  const auto resource_it = resource_by_mission.find(mission_id);
   152	  if (resource_it == resource_by_mission.end()) {
   153	    return false;
   154	  }
   155	  const auto reservation_it = reservations.find(resource_it->second);
   156	  if (reservation_it == reservations.end()) {
   157	    return false;
   158	  }
   159	  if (reservation_it->second.hold_after_completion) {
   160	    reservation_it->second.status = "occupied";
   161	  } else {
   162	    reservations.erase(reservation_it);
   163	    resource_by_mission.erase(resource_it);
   164	  }
   165	  return true;
   166	}
   167	
   168	bool ReleaseResourceForMission(
   169	    FacilityReservationMap& reservations, MissionResourceMap& resource_by_mission,
   170	    const std::string& mission_id) {
   171	  const auto resource_it = resource_by_mission.find(mission_id);
   172	  if (resource_it == resource_by_mission.end()) {
   173	    return false;
   174	  }
   175	  const auto reservation_it = reservations.find(resource_it->second);
   176	  if (reservation_it != reservations.end() && reservation_it->second.mission_id == mission_id) {
   177	    reservations.erase(reservation_it);
   178	  }
   179	  resource_by_mission.erase(resource_it);
   180	  return true;
   181	}
   182	
   183	}  // namespace amr_dispatcher_core::facility
