     5	bool FacilityActionSupported(const std::string& resource_type, const std::string& action) {
     6	  if (resource_type == "door") {
     7	    return action == "open" || action == "close" || action == "pass";
     8	  }
     9	  if (resource_type == "elevator") {
    10	    return action == "call" || action == "enter" || action == "exit" || action == "ride";
    11	  }
    12	  if (resource_type == "charger") {
    13	    return action == "reserve" || action == "release";
    14	  }
    15	  return action == "reserve" || action == "release" || action == "use";
    16	}
    17	
    18	FacilityActionResourceSelection SelectFacilityActionResource(
    19	    const FacilityCatalog& catalog, const FacilityReservationMap& reservations,
    20	    const std::string& requested_resource_id, const std::string& requested_resource_type) {
    21	  FacilityActionResourceSelection selection;
    22	  if (!requested_resource_id.empty()) {
    23	    const auto* resource = FindFacilityResource(catalog, requested_resource_id);
    24	    if (resource == nullptr) {
    25	      selection.message = "unknown facility resource: " + requested_resource_id;
    26	      return selection;
    27	    }
    28	    if (!requested_resource_type.empty() && resource->type != requested_resource_type) {
    29	      selection.message = "facility resource type mismatch: " + requested_resource_id;
    30	      return selection;
    31	    }
    32	    if (!FacilityResourceAvailable(*resource, reservations)) {
    33	      selection.message = "facility resource unavailable: " + requested_resource_id;
    34	      return selection;
    35	    }
    36	    selection.success = true;
    37	    selection.resource = resource;
    38	    return selection;
    39	  }
    40	
    41	  if (requested_resource_type.empty()) {
    42	    selection.message = "resource_id or resource_type is required";
    43	    return selection;
    44	  }
    45	  const auto* resource =
    46	      FindFirstAvailableResource(catalog, requested_resource_type, ReservedResourceIds(reservations));
    47	  if (resource == nullptr) {
    48	    selection.message = "no available facility resource of type: " + requested_resource_type;
    49	    return selection;
    50	  }
    51	  selection.success = true;
    52	  selection.resource = resource;
    53	  return selection;
    54	}
