    80	
    81	LiftSessionResult ReserveLiftSessionResource(
    82	    FacilityReservationMap& reservations, const FacilityResource& lift,
    83	    const std::string& session_id, const std::string& holder_id,
    84	    const bool release_existing_for_holder) {
    85	  LiftSessionResult result;
    86	  result.session_id = session_id;
    87	  result.lift_id = lift.id;
    88	
    89	  const auto existing = reservations.find(lift.id);
    90	  if (existing != reservations.end() && existing->second.holder_id != holder_id) {
    91	    // A6 先查后放（同型修复）：冲突失败不得释放 holder 的既有持有
    92	    result.status = existing->second.status;
    93	    result.message = "lift already reserved by " + existing->second.holder_id;
    94	    return result;
    95	  }
    96	  // 冲突检查通过后才释放 holder 的旧持有
    97	  if (release_existing_for_holder) {
    98	    ReleaseResourcesForHolder(reservations, holder_id);
    99	  }
   100	
   101	  reservations[lift.id] = ResourceReservation{holder_id, session_id, "lift_session", true};
   102	  result.success = true;
   103	  result.status = "lift_session";
   104	  result.message = "reserved lift " + lift.id + " for session " + session_id;
   105	  return result;
   106	}
   107	
   108	LiftSessionResult ReleaseLiftSessionResource(
   109	    FacilityReservationMap& reservations, const std::string& lift_id,
   110	    const std::string& session_id) {
   111	  LiftSessionResult result;
   112	  result.lift_id = lift_id;
   113	  result.session_id = session_id;
   114	
   115	  const auto existing = reservations.find(lift_id);
   116	  if (existing == reservations.end()) {
   117	    result.success = true;
   118	    result.status = "available";
   119	    result.message = "lift already available: " + lift_id;
   120	    return result;
   121	  }
