    20	    const std::string& requested_resource_id, const std::string& requested_resource_type) {
    21	  FacilityActionResourceSelection selection;
    22	  if (!requested_resource_id.empty()) {
    23	    const auto* resource = FindFacilityResource(catalog, requested_resource_id);
    24	    if (resource == nullptr) {
    25	      selection.message = "unknown facility resource: " + requested_resource_id;
    26	      return selection;
    27	    }
    28	    if (!requested_resource_type.empty() && resource->type != requested_resource_type) {
    29	      selection.message = "facility resource type mismatch: " + requested_resource_id;
    30	      return selection;
