    49	                        std::chrono::steady_clock::time_point start,
    50	                        std::chrono::steady_clock::time_point end,
    51	                        std::string* message);
    52	
    53	  // 释放某任务持有的全部资源（含时空预约），返回是否实际删除。
    54	  ReleaseResult Release(const std::string& mission_id);
    55	
    56	  // 逐段动态解锁：仅释放 owner == mission_id 且列于 resource_ids 的锁。
    57	  // 他人锁（含 traffic_block）、未持有/已释放的 id 一律跳过（对未持有 id 是安全 no-op）。
    58	  // 返回实际删除的 resource_id 列表（保序、与入参一致），供幂等重算与日志取证。
    59	  // 注意：只处理静态锁；时空预约不在逐段释放语义内（Release(mission) 才全清）。
    60	  std::vector<std::string> ReleaseResources(
    61	      const std::string& mission_id, const std::vector<std::string>& resource_ids);
    62	
    63	  // 时空预约**批量**提交（全有或全无）：一条路径涉及多个资源，
    64	  // 必须整条路径全部预约成功才落表；任一失败则全部回滚，不留半套预约。
    65	  // 逐个调用 ReserveTimeSpace 无法保证这一点（中途失败会留下前面的预约）。
    66	  // 返回失败时 message 给出冲突资源与占用方。
    67	  bool ReserveTimeSpaceBatch(
    68	      const std::string& mission_id,
    69	      const std::vector<std::pair<std::string, TimeInterval>>& resource_intervals,
    70	      std::string* message);
    71	
    72	  // 延长某任务在某资源上的时空窗口（车辆执行滞后时用）。
    73	  // 延长区间与他人预约冲突则不改动（返回 false）。
    74	  bool ExtendTimeSpaceReservation(const std::string& mission_id, const std::string& resource_id,
    75	                                  const std::chrono::steady_clock::time_point& new_end,
    76	                                  std::string* message);
    77	
    78	  // 逐资源释放某任务持有的时空预约区间（车辆**确认驶离**后调用）。
    79	  //   * 只释放 owner == mission_id 的区间，他人区间不动；
    80	  //   * 该任务在某资源上没有区间 -> 幂等跳过；
    81	  // 返回实际释放的资源 id 列表（保序）。
    82	  // 评审 B.2：窗口到期 != 资源已释放——物理释放必须由确认驶离驱动。
    83	  std::vector<std::string> ReleaseTimeSpaceResources(
    84	      const std::string& mission_id, const std::vector<std::string>& resource_ids);
    85	
    86	  // 人工封路：owner = "traffic_block:<reason>"，对任务预留不可见覆盖。
    87	  bool Block(const std::string& resource_id, const std::string& reason, std::string* message);
    88	  bool Unblock(const std::string& resource_id, std::string* message);
    89	
    90	  bool Locked(const std::string& resource_id) const;
    91	  std::optional<std::string> Owner(const std::string& resource_id) const;
    92	  std::size_t size() const { return locks_.size(); }
    93	
    94	  // 时空预约表当前有效条目总数（过期回收的可观测指标）
    95	  std::size_t TimeSpaceReservationCount() const;
    96	
    97	  // 某任务当前持有的**时空预约**资源 id 列表（按资源 id 排序）。
    98	  // 与 Snapshot()（静态锁）互补：time_space 模式下"本单获准通行哪些资源"
    99	  // 要从时空预约表读，不能从静态锁表读。
   100	  std::vector<std::string> TimeSpaceResourcesOf(const std::string& mission_id) const;
   101	
   102	  std::vector<std::pair<std::string, std::string>> Snapshot() const;  // 已排序
   103	
   104	  // 资源命名规则。
   105	  static std::string RouteEdgeId(const std::string& from, const std::string& to);
   106	  static std::string RouteNodeId(const std::string& station_id);
   107	  static std::vector<std::string> BuildLockIds(
   108	      const std::vector<std::string>& station_path, bool include_intersection_locks);
   109	  static std::optional<std::pair<std::string, std::string>> ParseRouteEdge(
   110	      const std::string& resource_id);
   111	  static bool IsTrafficBlockOwner(const std::string& owner_id);
   112	
   113	 private:
   114	  std::unordered_map<std::string, std::string> locks_;  // resource_id → owner
   115	  // resource_id -> 所有的时空预约区间
   116	  std::unordered_map<std::string, std::vector<TimeSpaceReservation>> time_space_reservations_;
   117	};
