=== udp impl ===
     1	#include "amr_dispatcher_core/chassis/udp_backend.hpp"
     2	
     3	#include <arpa/inet.h>
     4	#include <cerrno>
     5	#include <cstring>
     6	#include <string>
     7	#include <sys/socket.h>
     8	#include <unistd.h>
     9	#include <utility>
    10	
    11	namespace amr_dispatcher_core::chassis {
    12	
    13	UdpBackend::UdpBackend(ChassisBackendConfig config) : config_(std::move(config)) {}
    14	
    15	UdpBackend::~UdpBackend() { Close(); }
    16	
    17	std::string UdpBackend::Name() const { return "udp"; }
    18	
    19	bool UdpBackend::Open(std::string* error) {
    20	  Close();
    21	  fd_ = socket(AF_INET, SOCK_DGRAM | SOCK_NONBLOCK, 0);
    22	  if (fd_ < 0) {
    23	    if (error != nullptr) {
    24	      *error = "failed to create UDP backend socket: " + std::string(std::strerror(errno));
    25	    }
    26	    return false;
    27	  }
    28	  remote_addr_ = {};
    29	  remote_addr_.sin_family = AF_INET;
    30	  remote_addr_.sin_port = htons(static_cast<uint16_t>(config_.udp_port));
    31	  if (inet_pton(AF_INET, config_.udp_host.c_str(), &remote_addr_.sin_addr) != 1) {
    32	    if (error != nullptr) {
    33	      *error = "invalid UDP backend host '" + config_.udp_host + "'";
    34	    }
    35	    Close();
    36	    return false;
    37	  }
    38	  return true;
    39	}
    40	
    41	void UdpBackend::Close() {
    42	  if (fd_ >= 0) {
    43	    close(fd_);
    44	    fd_ = -1;
    45	  }
    46	}
    47	
    48	bool UdpBackend::IsOpen() const { return fd_ >= 0; }
    49	
    50	bool UdpBackend::WriteCommand(const ChassisCommand& command, std::string* error) {
    51	  if (!IsOpen()) {
    52	    if (error != nullptr) {
    53	      *error = "UDP backend is not open";
    54	    }
    55	    return false;
    56	  }
    57	  const auto binary_packet = EncodeMickSpeedCommand(command);
    58	  const std::string text_packet = EncodeCommand(command);
    59	  const char* data = config_.protocol == "mick_binary"
    60	                         ? reinterpret_cast<const char*>(binary_packet.data())
    61	                         : text_packet.data();
    62	  const std::size_t size = config_.protocol == "mick_binary" ? binary_packet.size()
    63	                                                             : text_packet.size();
    64	  const ssize_t sent =
    65	      sendto(fd_, data, size, 0,
    66	             reinterpret_cast<const sockaddr*>(&remote_addr_), sizeof(remote_addr_));
    67	  // 数据报语义：sendto 要么整报发出要么失败，不存在可重试的"部分发送"（不做分片循环，
    68	  // 否则短计数会把一帧拆成多个数据报）。would-block 同串口语义按本帧丢失处理。
    69	  if (sent < 0) {
    70	    if (error != nullptr) {
    71	      *error = std::strerror(errno);
    72	    }
    73	    return false;
    74	  }
    75	  if (static_cast<std::size_t>(sent) != size) {
    76	    if (error != nullptr) {
    77	      *error = "UDP send returned short count";
    78	    }
    79	    return false;
    80	  }
    81	  return true;
    82	}
    83	
    84	std::optional<std::string> UdpBackend::Read(std::string* error) {
    85	  if (!IsOpen()) {
    86	    return std::nullopt;
    87	  }
    88	  char buffer[512];
    89	  sockaddr_in from {};
    90	  socklen_t from_len = sizeof(from);
    91	  const ssize_t received =
    92	      recvfrom(fd_, buffer, sizeof(buffer), 0, reinterpret_cast<sockaddr*>(&from), &from_len);
    93	  if (received < 0) {
    94	    if (errno != EAGAIN && errno != EWOULDBLOCK && error != nullptr) {
    95	      *error = std::strerror(errno);
    96	    }
    97	    return std::nullopt;
    98	  }
    99	  if (received == 0) {
   100	    return std::nullopt;
   101	  }
   102	  return std::string(buffer, static_cast<std::size_t>(received));
   103	}
   104	
   105	}  // namespace amr_dispatcher_core::chassis

