    31	  const FacilityResource* selected_resource = nullptr;
    32	  FacilityActionBehaviorTreeResult result;
    33	};
    34	
    35	FacilityActionBtContext MakeFacilityActionContext(
    36	    const FacilityActionBehaviorTreeInput& input) {
    37	  FacilityActionBtContext context;
    38	  context.input = input;
    39	  context.result.reservations = input.reservations;
