     1	// 充电任务自动编排（纯函数）。
     2	//
     3	// 现状：core 里已有 `PlanOpportunityCharging`（按**电压**判定），但它只被单测
     4	// 调用，调度器从不使用；调度器能看到的电量是**百分比**（VehicleRuntimeState /
     5	// VDA 5050 batteryCharge），而且"该不该给这台车插一条充电单"还要看：车是否
     6	// 空闲、在线、未隔离、是否已经有一张在跑/在排的充电单、充电站是否存在。
     7	//
     8	// 这里把这套判定独立成纯函数，供每个 tick 对每台车调用一次：
     9	//   * 关闭（默认）-> 什么都不做
    10	//   * 电量高于机会阈值 -> 不插单
    11	//   * 该车已有充电单（排队或在途）-> 不重复插单（否则每 tick 插一条）
    12	//   * 车忙 / 离线 / 隔离 -> 不插单（充电也要占执行槽位，车忙时插单只会堆积）
    13	//   * 充电站未知 -> 不插单（不猜站点）
    14	//   * 否则 -> 插一条 charge 单，临界电量用更高优先级
    15	//
    16	// 铁律：本函数**只产决策**，不碰队列、不碰日志。插单与去重记账由 ROS 侧落地。
    17	#pragma once
    18	
    19	#include <string>
    20	
    21	namespace amr_dispatcher_core::workflow {
    22	
    23	struct AutoChargingRequest {
    24	  bool enabled = false;
    25	  std::string vehicle_id;
    26	
    27	  // 车辆运行时状态
    28	  bool online = true;
    29	  bool busy = false;
    30	  bool quarantined = false;
    31	  double battery_percent = 100.0;
    32	  bool battery_known = true;
    33	
    34	  // 该车当前是否已有充电单（排队或在途）—— 去重键是"车"，不是"站点"
    35	  bool has_pending_charge_mission = false;
    36	
    37	  // 充电目标站（由调用方解析后传入）
    38	  std::string charger_station_id;
    39	  bool charger_station_known = false;
    40	
    41	  // 阈值与优先级
    42	  double opportunity_threshold_percent = 30.0;
    43	  double critical_threshold_percent = 15.0;
    44	  int opportunity_priority = 0;
    45	  int critical_priority = 5;
    46	};
    47	
    48	struct AutoChargingDecision {
    49	  enum class Kind {
    50	    kDisabled,        // 功能关闭
    51	    kBatteryUnknown,  // 没有电量信息：不插单（不猜）
    52	    kBatteryOk,       // 电量高于机会阈值
    53	    kAlreadyQueued,   // 该车已有充电单
    54	    kVehicleUnavailable,  // 忙 / 离线 / 隔离
    55	    kChargerUnknown,  // 充电站未解析
    56	    kQueueCharge,     // 插单
    57	  };
    58	  Kind kind = Kind::kDisabled;
    59	  bool critical = false;
    60	  int priority = 0;
    61	  std::string charger_station_id;
    62	  std::string reason;
    63	};
    64	
    65	AutoChargingDecision PlanAutoCharging(const AutoChargingRequest& request);
    66	
    67	}  // namespace amr_dispatcher_core::workflow
