     1	// 交通冲突与死锁分级恢复协调器（纯函数）。
     2	//
     3	// 对应 Phase 7 (P2)：
     4	// 当 DeadlockDetector 识别出 WFG 互斥死锁环时，本模块对死锁环进行策略分析与破环裁决：
     5	// 1. 优先选择环中具有可行替代路线的任务进行拓扑绕行（BreakCycleByReroute）。
     6	// 2. 若涉及多台车，优先重规划优先级较低或绕行代价较小的车辆。
     7	// 3. 若所有涉案车辆均无替代路线（如窄道互卡死胡同），则裁定转入受控安全等待/挂起（kRecoveryFailed），
     8	//    绝不盲动或随意倒车。
     9	#pragma once
    10	
    11	#include <string>
    12	#include <vector>
    13	
    14	#include "amr_dispatcher_core/catalog/station_catalog.hpp"
    15	#include "amr_dispatcher_core/dispatcher/deadlock_detector.hpp"
    16	#include "amr_dispatcher_core/workflow/in_flight_reroute_planning.hpp"
    17	
    18	namespace amr_dispatcher_core::workflow {
    19	
    20	struct DeadlockRecoveryCandidate {
    21	  std::string mission_id;
    22	  std::string vehicle_id;
    23	  int priority = 0;
    24	  std::string current_safe_node;
    25	  std::string destination_node;
    26	  std::vector<std::string> current_held_locks;
    27	  std::vector<std::string> full_original_path;
    28	};
    29	
    30	struct DeadlockRecoveryRequest {
    31	  std::vector<std::string> cycle_mission_ids;       // 死锁环中包含的任务列表
    32	  std::unordered_set<std::string> cycle_blocked_edges;// 死锁环中发生冲突的边
    33	  std::vector<DeadlockRecoveryCandidate> candidates; // 涉案任务详细状态
    34	  const catalog::StationCatalog* catalog = nullptr;
    35	};
    36	
    37	struct DeadlockRecoveryDecision {
    38	  enum class Action {
    39	    kRerouteMission,    // 选定其中某任务执行安全绕行以破环
    40	    kSafeStopSuspend,   // 无法绕行，下发驻车并在道口等待
    41	    kNoActionNeeded,    // 无死锁环或参数无效
    42	  };
    43	
    44	  Action action = Action::kNoActionNeeded;
    45	  std::string selected_mission_id;
    46	  InFlightRerouteDecision reroute_decision;
    47	  std::string message;
    48	};
    49	
    50	DeadlockRecoveryDecision PlanDeadlockRecovery(const DeadlockRecoveryRequest& request);
    51	
    52	}  // namespace amr_dispatcher_core::workflow

