    10	namespace amr_dispatcher_core::fleet {
    11	
    12	// 车队协议适配层的统一数据模型与控制接口。
    13	// 调度核心只依赖本文件中的抽象，不感知具体厂商协议（VDA 5050 / 私有协议等）。
    14	
    15	/// 单个车辆动作，挂载在节点或边上（VDA 5050 action）。
    16	struct VehicleAction {
    17	  std::string action_type;  // e.g. "lift", "drop", "charge", "beep"
    18	  std::string action_id;
    19	  std::unordered_map<std::string, std::string> parameters;
    20	};
    21	
    22	/// 车辆轨迹折线点（边内的几何路径点）。
    23	struct VehicleTrajectoryPoint {
    24	  double x = 0.0;
    25	  double y = 0.0;
    26	  double yaw = 0.0;
    27	};
    28	
    29	/// 订单中的一条边（含路权放行标记与行驶折线）。
    30	struct VehicleEdge {
    31	  std::string edge_id;
    32	  std::string start_node_id;
    33	  std::string end_node_id;
    34	  bool released = true;
    35	  double max_speed = 1.0;
    36	  std::vector<VehicleTrajectoryPoint> polyline;
    37	  std::vector<VehicleAction> actions;
    38	};
    39	
    40	/// 订单中的一个节点（含序号、路权放行标记与挂载动作）。
    41	struct VehicleNode {
    42	  std::string node_id;
    43	  uint32_t sequence_id = 0;
    44	  bool released = true;
    45	  double x = 0.0;
    46	  double y = 0.0;
    47	  double yaw = 0.0;
    48	  std::vector<VehicleAction> actions;
    49	};
    50	
    51	/// 一次完整的派车订单。
    52	struct VehicleOrder {
    53	  std::string order_id;
    54	  uint32_t order_update_id = 0;
    55	  std::string vehicle_id;
    56	  std::vector<VehicleNode> nodes;
    57	  std::vector<VehicleEdge> edges;
    58	};
    59	
    60	/// 车辆上报的归一化状态。
    61	struct VehicleStateReport {
    62	  std::string vehicle_id;
    63	  std::string order_id;
    64	  uint32_t last_node_sequence_id = 0;
    65	  std::string last_node_id;
    66	  double x = 0.0;
    67	  double y = 0.0;
    68	  double yaw = 0.0;
    69	  // 定位是否已初始化（VDA 5050 agvPosition.positionInitialized）。
    70	  // false -> 车辆位置不可信 -> 选车时该车**不合格**（不盲派）。
    71	  bool agv_position_initialized = false;
    72	  double battery_percent = 100.0;
    73	  bool is_charging = false;
    74	  bool estop_active = false;
    75	  bool online = true;
    76	  std::string operating_mode = "AUTOMATIC";
    77	  std::vector<std::string> active_errors;
    78	  std::chrono::steady_clock::time_point last_report_time = std::chrono::steady_clock::now();
    79	};
    80	
