    10	// 任务生命周期状态：4 态 + 结果分离设计。
    11	//
    12	//   kPending ──► kActive ──► kFinished
    13	//       ▲  │        │  ▲
    14	//       │  ▼        ▼  │
    15	//       └─ kPaused ◄───┘
    16	//
    17	// 终态结果（kSucceeded/kFailed/kCanceled）与状态正交，单独记录，
    18	// 避免用状态字符串编码结果导致的组合爆炸。
    19	enum class MissionState { kPending, kActive, kPaused, kFinished };
    20	
    21	enum class MissionResult { kNone, kSucceeded, kFailed, kCanceled };
