  if (!node[key]) {
    out->clear();
    return true;
  }
  try {
    *out = node[key].as<std::string>();
    return true;
  } catch (const YAML::Exception& e) {
    if (err != nullptr) *err = std::string("field '") + key + "' is not a string: " + e.what();
    return false;
  }
}

